INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_NOR_FJALAR_DWARF_PROSE_','ENT_NOR_FJALAR_DWARF','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','Once he came to the home of the dwarfs Fjalar and Galar. They called him aside, saying they wished to speak with him alone, slew him and let his blood run into two jars called Son and Bodn, and into a kettle called Odrarer. They mixed honey with the blood, and thus was produced such mead that whoever drinks from it becomes a skald and sage.','Arthur G. Brodeur',1916,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_FULLA_PROSE_','ENT_NOR_FULLA','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','The fifth is Fulla, who is also a may, she wears her hair flowing and has a golden ribbon about her head; she carries Frigg''s chest, takes care of her shoes and knows her secrets. The sixth is Freyja, who is ranked with Frigg. She is wedded to the man whose name is Oder; their daughter''s name is Hnos, and she is so fair that all things fair and precious are called, from her name, Hnos. Oder went far away.','Arthur G. Brodeur',1916,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_GALAR_PROSE_','ENT_NOR_GALAR','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','Once he came to the home of the dwarfs Fjalar and Galar. They called him aside, saying they wished to speak with him alone, slew him and let his blood run into two jars called Son and Bodn, and into a kettle called Odrarer. They mixed honey with the blood, and thus was produced such mead that whoever drinks from it becomes a skald and sage.','Arthur G. Brodeur',1916,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_GEIRROD_GIANT_PROSE_','ENT_NOR_GEIRROD_GIANT','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','Thor and Hrungner 169 Thor''s Journey to Geirrod''s 176 Idun 184 Aeger''s Feast 187 Loke''s Wager with the Dwarfs 189 The Niflungs and Gjukungs 193 Menja and Fenja 206 The Grottesong 208 Rolf Krake 214 Hogne and Hild 218 NOTES.','Arthur G. Brodeur',1916,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_LAUFEY_PROSE_','ENT_NOR_LAUFEY','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','His father is the giant Farbaute, but his mother''s name is Laufey, or Nal. His brothers are Byleist and Helblinde. Loke is fair and beautiful of face, but evil in disposition, and very fickle-minded. He surpasses other men in the craft called cunning, and cheats in all things. He has often brought the asas into great trouble, and often helped them out again, with his cunning contrivances.','Arthur G. Brodeur',1916,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_NANNA_PROSE_','ENT_NOR_NANNA','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','Balder''s corpse was borne out on the ship; and when his wife, Nanna, daughter of Nep, saw this, her heart was broken with grief and she died. She was borne to the funeral-pile and cast on the fire. Thor stood by and hallowed the pile with Mjolner. Before his feet ran a dwarf, whose name is Lit. Him Thor kicked with his foot and dashed him into the fire, and he, too, was burned.','Arthur G. Brodeur',1916,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NORR_ALFHEIM_PROSE_','ENT_NORR_ALFHEIM','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','One is there called Alfheim. There dwell the folk that are called light-elves; but the dark-elves dwell down in the earth, and they are unlike the light-elves in appearance, but much more so in deeds. The light-elves are fairer than the sun to look upon, but the dark-elves are blacker than pitch. Another place is called Breidablik, and no place is fairer.','Arthur G. Brodeur',1916,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NORR_ASGARD_PROSE_','ENT_NORR_ASGARD','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','Gylfe''s Journey to Asgard 51 CHAPTER III. Of the Highest God 54 CHAPTER IV. The Creation of the World 56 CHAPTER V. The Creation (continued) 64 CHAPTER VI. The First Works of the Asas--The Golden Age 69 CHAPTER VII. On the Wonderful Things in Heaven 72 CHAPTER VIII. The Asas 79 CHAPTER IX. Loke and his Offspring 91 CHAPTER X. The Goddesses (Asynjes) 97 CHAPTER XI. The Giantess Gerd and Skirner''s Journey 101 CHAPTER XII.','Arthur G. Brodeur',1916,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NORR_JOTUNHEIM_PROSE_','ENT_NORR_JOTUNHEIM','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','She took from the north, from Jotunheim, four oxen, which were the sons of a giant and her, and set them before the plow. Then went the plow so hard and deep that it tore up the land, and the oxen drew it westward into the sea, until it stood still in a sound. There Gefjun set the land, gave it a name and called it Seeland.','Arthur G. Brodeur',1916,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NORR_MIDGARD_PROSE_','ENT_NORR_MIDGARD','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','And straightway Odin and his brothers--the bright sons of Bure--gave Ymer a mortal wound, and from his body made they the universe; from his flesh, the earth; from his blood, the sea; from his bones, the rocks; from his hair, the trees; from his skull, the vaulted heavens; from his eye-brows, the bulwark called Midgard.','Arthur G. Brodeur',1916,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NORR_MUSPELHEIM_PROSE_','ENT_NORR_MUSPELHEIM','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','In the beginning, before the heaven and the earth and the sea were created, the great abyss Ginungagap was without form and void, and the spirit of Fimbultyr moved upon the face of the deep, until the ice-cold rivers, the Elivogs, flowing from Niflheim, came in contact with the dazzling flames from Muspelheim. This was before Chaos.','Arthur G. Brodeur',1916,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NORR_NIFLHEIM_PROSE_','ENT_NORR_NIFLHEIM','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','In the beginning, before the heaven and the earth and the sea were created, the great abyss Ginungagap was without form and void, and the spirit of Fimbultyr moved upon the face of the deep, until the ice-cold rivers, the Elivogs, flowing from Niflheim, came in contact with the dazzling flames from Muspelheim. This was before Chaos.','Arthur G. Brodeur',1916,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_SIGYN_PROSE_','ENT_NOR_SIGYN','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','But Sigyn, his wife, stands by him, and holds a dish under the venom-drops. Whenever the dish becomes full, she goes and pours away the venom, and meanwhile the venom drops onto Loke''s face. Then he twists his body so violently that the whole earth shakes, and this you call earthquakes. There he will lie bound until Ragnarok. CHAPTER XVI. RAGNAROK. 55.','Arthur G. Brodeur',1916,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_VIDAR_PROSE_','ENT_NOR_VIDAR','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','Odin''s son goes To fight with the wolf, And Vidar goes on his way To the wild beast. With his hand he thrusts His sword to the heart Of the giant''s child, And avenges his father. Then goes the famous Son of Hlodyn To fight with the serpent. Though about to die, He fears not the contest; All men Abandon their homesteads When the warder of Midgard In wrath slays the serpent.','Arthur G. Brodeur',1916,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1)
